use vstd::prelude::*;

verus! {
    fn longest_increasing_streak(nums: &Vec<i32>) -> (max_streak: usize)
        requires
            nums.len() <= 0x1_0000_0000, // Ensure the length of nums is within bounds
        ensures
            max_streak <= nums.len(), // The maximum streak cannot exceed the length of the array
            (nums.is_empty() ==> max_streak == 0) // If nums is empty, max_streak should be 0
    {
        if nums.is_empty() {
            return 0;
        }

        let mut max_streak = 1;
        let mut current_streak = 1;

        // Loop invariant to maintain the properties during the iteration
        for i in 1..nums.len()
            invariant
                1 <= i <= nums.len(), // i is within bounds
                current_streak <= nums.len(), // current_streak cannot exceed the length of nums
                max_streak <= nums.len(), // max_streak cannot exceed the length of nums
                (i == nums.len() ==> max_streak == current_streak || max_streak == max_streak), // At the end of the loop, max_streak should be updated correctly
        {
            if nums[i] > nums[i - 1] {
                current_streak += 1;
            } else {
                if current_streak > max_streak {
                    max_streak = current_streak;
                }
                current_streak = 1; // Reset current streak
            }
        }

        // Final check to update max_streak
        if current_streak > max_streak {
            max_streak = current_streak;
        }

        max_streak
    }
}

